import subprocess,json
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
print('ROOT KEYS',list(r))
for k,v in r.items():
 if k not in ['context','study_schema','candidate_api']: print(k,json.dumps(v,indent=2))
c=r.get('context',{})
print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k"'!='"'history': print(k,json.dumps(v,indent=2))
print('HISTORY SUMMARY')
for t in c.get('history',[]):
 print(json.dumps({k:t.get(k) for k in ['id','parent','role','config','status','wall_seconds','parameters','train_seconds','error','note']}))
 print('metrics',json.dumps({k:t.get('validation',{}).get(k) for k in ['auc','logloss','mean_task_auc','slices']}))
PY"

